def is_in_G(n, a, b):
    if n < 0:
        return False
    # Check if n = a*k1 + b*k2 for k1, k2 >= 0
    # We can iterate k1 from 0 up to n/a
    for k1 in range(n // a + 1):
        remainder = n - a * k1
        if remainder >= 0 and remainder % b == 0:
            return True
    return False

