def get_closure(start_node_index, adj_list):
    closure = {start_node_index}
    queue = [start_node_index]
    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        for v in adj_list[u]:
            if v not in closure:
                closure.add(v)
                queue.append(v)
    return frozenset(closure) # Use frozenset for hashing

